from pathlib import Path
import json,re

sent=Path.home()/'.local/share/prediction-chat-bridge/sent'

def load_event(event_id):
    p=sent/f'{event_id}.json'
    if not p.is_file():
        return None, f'MISSING:{p}'
    try:
        obj=json.loads(p.read_text(encoding='utf-8',errors='replace'))
    except Exception as exc:
        return None, f'BAD_JSON:{exc.__class__.__name__}'
    return str(obj.get('message') or ''), None

def compact_astra(raw):
    if raw is None:
        return 'ASTRA_FIRSTFAIL=RAW_EVENT_MISSING'
    lines=raw.splitlines()
    test=''
    for ln in lines:
        s=ln.strip()
        if re.search(r'tests/.+::.+\s+FAILED(?:\s|$)',s):
            test=s
            break
    if not test:
        for ln in lines:
            s=ln.strip()
            if s.startswith('FAILED ') and '::' in s:
                test=s
                break
    details=[]
    in_fail=False
    for ln in lines:
        s=ln.rstrip()
        if ' FAILURES ' in s or s.startswith('___'):
            in_fail=True
        if in_fail and (s.startswith('E ') or 'AssertionError' in s or 'assert ' in s or 'KeyError' in s or 'TypeError' in s or 'ValueError' in s):
            details.append(re.sub(r'\s+',' ',s).strip())
    if not details:
        for ln in lines:
            s=ln.strip()
            if s.startswith('E ') or 'AssertionError' in s:
                details.append(re.sub(r'\s+',' ',s))
    return 'ASTRA_FIRSTFAIL='+(test or 'UNKNOWN')+' || '+(' | '.join(details[-4:])[:1100] if details else 'NO_ASSERTION_TEXT')

def compact_diff(raw):
    if raw is None:
        return 'PROD_STAGED_DIFF=RAW_EVENT_MISSING'
    payload=None
    for ln in raw.splitlines():
        if ln.startswith('PRODUCTION_DIFF_INSPECT '):
            try:
                payload=json.loads(ln.split(' ',1)[1])
            except Exception:
                pass
    if payload is None:
        m=re.search(r'PRODUCTION_DIFF_INSPECT\s+(\{.*\})',raw,re.S)
        if m:
            try: payload=json.loads(m.group(1))
            except Exception: pass
    if payload is None:
        return 'PROD_STAGED_DIFF=PAYLOAD_NOT_FOUND'
    diff=str(payload.get('diff') or '')
    files=[]
    stats={}
    cur=None
    for line in diff.splitlines():
        if line.startswith('diff --git a/'):
            cur=line.split(' b/',1)[-1]
            if cur not in stats:
                files.append(cur);stats[cur]={'a':0,'d':0,'sig':[]}
        elif cur and line.startswith('+') and not line.startswith('+++'):
            stats[cur]['a']+=1
            s=line[1:].strip()
            if re.match(r'(def |class |async def |[A-Z][A-Z0-9_]{2,}\s*=)',s) and len(stats[cur]['sig'])<2:
                stats[cur]['sig'].append('+'+s[:90])
        elif cur and line.startswith('-') and not line.startswith('---'):
            stats[cur]['d']+=1
            s=line[1:].strip()
            if re.match(r'(def |class |async def |[A-Z][A-Z0-9_]{2,}\s*=)',s) and len(stats[cur]['sig'])<2:
                stats[cur]['sig'].append('-'+s[:90])
    parts=[]
    for f in files:
        st=stats[f]
        sig=','.join(st['sig'])
        parts.append(f"{f}[+{st['a']}/-{st['d']}]" + (f"{{{sig}}}" if sig else ''))
    return 'PROD_STAGED_DIFF='+' | '.join(parts)[:1800]

a_raw,a_err=load_event('1791185094-b2ad1bd15dcb')
d_raw,d_err=load_event('1791185669-30977cb32a12')
print(compact_astra(a_raw) if not a_err else 'ASTRA_FIRSTFAIL='+a_err)
print(compact_diff(d_raw) if not d_err else 'PROD_STAGED_DIFF='+d_err)
raise SystemExit(42)
